    reveal aInvariant;
    reveal sInvariant;
    assert a.Length <= 1;
    assert oldASeq == a[..];
    assert oldS == s;
    if a.Length == 0 {
      assert Model.Shuffle(oldASeq)(oldS) == Monad.Return(oldASeq)(oldS);
      assert Monad.Return(oldASeq)(oldS) == Monad.Result(oldASeq, oldS);
      assert oldASeq == a[..];
      assert oldS == s;
    } else {
      assert a.Length == 1;
      assert |oldASeq| == 1;
      assert Model.Shuffle(oldASeq)(oldS) == Monad.Return(oldASeq)(oldS);
      assert Monad.Return(oldASeq)(oldS) == Monad.Result(oldASeq, oldS);
      assert oldASeq == a[..];
      assert oldS == s;
    }
  "}

